import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, Icon, StatusPill } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { profiles, presets, versions } from "./data.js";

function Toast({text}){return text&&html`<div class="p-profiles-toast" role="status">${text}</div>`}
function Action({children,onClick,primary=false,disabled=false}){return html`<button class=${`p-profiles-action ${primary?'primary':''}`} disabled=${disabled} onClick=${onClick}>${children}</button>`}
function ProfileList({selected,setSelected}){return html`<aside class="p-profiles-library"><header><span>PROFILE LIBRARY</span><button aria-label="Add profile">+</button></header><div class="p-profiles-search"><input aria-label="Search profiles" placeholder="Search templates"/><button aria-label="Filter profiles"><${Icon} name="sliders-horizontal"/></button></div><div class="p-profiles-library-list">${profiles.map(p=>html`<button class=${selected.id===p.id?'selected':''} onClick=${()=>setSelected(p)}><i class=${p.role}></i><span><b>${p.name}</b><small>${p.role} · ${p.model}</small></span><em>${p.version.split(' · ')[0]}</em></button>`)}</div><footer><span>3 profiles</span><span>2 assigned</span></footer></aside>`}
function ConfigSummary({profile}){return html`<aside class="p-profiles-effective"><p>EFFECTIVE CONFIG</p><h2>${profile.name}</h2><div class="p-profiles-effective-state"><${StatusPill} status="active"/><span>${profile.version}</span></div><dl><div><dt>Scope</dt><dd>${profile.org}<br/>${profile.projects.join(', ')}</dd></div><div><dt>Model</dt><dd>${profile.model}<br/>${profile.thinking} thinking</dd></div><div><dt>Budget</dt><dd>${profile.budget}</dd></div><div><dt>Approval</dt><dd>${profile.approval}</dd></div><div><dt>Tools</dt><dd>${profile.tools.join(' · ')}</dd></div></dl><div class="p-profiles-effective-callout"><b>Applied at dispatch</b><span>Agent-specific limits can only reduce these grants.</span></div></aside>`}
function FormEditor({profile,dirty,setDirty,toast}){const [name,setName]=useState(profile.name);const [model,setModel]=useState(profile.model);const valid=name.trim().length>2;return html`<section class="p-profiles-form-editor"><header><div><p>EDITING TEMPLATE</p><h1>${profile.name}</h1><span>Reusable policy for agents and assignments.</span></div><div class="p-profiles-header-actions"><${Action} onClick=${()=>toast('Copy created as draft')}>Duplicate</${Action}><${Action} onClick=${()=>toast('Test run queued against sandbox')}>Test run</${Action}><${Action} primary=${true} disabled=${!valid} onClick=${()=>{setDirty(false);toast('Profile v13 saved')}}>Save ${dirty?'changes':''}</${Action}></div></header>${!valid&&html`<div class="p-profiles-validation">A profile name needs at least 3 characters.</div>`}<div class="p-profiles-editor-fields"><label>Name<input value=${name} onInput=${e=>{setName(e.target.value);setDirty(true)}}/></label><label>Role<select onChange=${()=>setDirty(true)}><option>${profile.role}</option><option>steward</option><option>scout</option><option>worker</option><option>reviewer</option></select></label><label>Model<select value=${model} onChange=${e=>{setModel(e.target.value);setDirty(true)}}><option>Claude Sonnet 4.5</option><option>Claude Haiku 4.5</option></select></label><label>Thinking level<select onChange=${()=>setDirty(true)}><option>${profile.thinking}</option><option>Low</option><option>Medium</option><option>High</option></select></label><label class="wide">Instructions<textarea onInput=${()=>setDirty(true)}>${profile.prompt}</textarea></label><fieldset><legend>Tool allowlist</legend>${['read','search','write','test','github'].map(tool=>html`<label><input type="checkbox" checked=${profile.tools.includes(tool)} onChange=${()=>setDirty(true)}/> ${tool}</label>`)}</fieldset><fieldset><legend>Guardrails</legend><label>Run cap<input value=${profile.budget} onInput=${()=>setDirty(true)}/></label><label>Approval<select onChange=${()=>setDirty(true)}><option>${profile.approval}</option><option>Never merge</option><option>PR required</option></select></label></fieldset></div></section>`}
function Library({toast}){const [selected,setSelected]=useState(profiles[0]);const [dirty,setDirty]=useState(false);return html`<section class="p-profiles-workspace"><${ProfileList} selected=${selected} setSelected=${p=>{setSelected(p);setDirty(false)}}/><${FormEditor} profile=${selected} dirty=${dirty} setDirty=${setDirty} toast=${toast}/><${ConfigSummary} profile=${selected}/>${dirty&&html`<div class="p-profiles-unsaved">Unsaved changes <button onClick=${()=>setDirty(false)}>Discard</button></div>`}</section>`}
function Wizard({toast}){const [step,setStep]=useState(0);const [chosen,setChosen]=useState(null);const steps=['Identity','Model','Tools','Guardrails','Review'];return html`<section class="p-profiles-wizard"><header><div><p>NEW AGENT PROFILE</p><h1>Set the operating envelope.</h1></div><span>Draft · not assigned</span></header><div class="p-profiles-wizard-body"><aside><b>SETUP</b>${steps.map((x,i)=>html`<button class=${i===step?'on':i<step?'done':''} onClick=${()=>setStep(i)}><i>${i<step?'✓':i+1}</i>${x}</button>`)}</aside><main>${step===0&&html`<div class="p-profiles-wizard-panel"><p class="p-profiles-kicker">START FROM A SHAPE</p><h2>What should this profile do?</h2><div class="p-profiles-preset-grid">${presets.map(p=>html`<button class=${chosen===p.name?'selected':''} onClick=${()=>setChosen(p.name)}><i>${p.icon}</i><b>${p.name}</b><span>${p.copy}</span></button>`)}</div><label>Profile name<input placeholder="e.g. Dependency reviewer"/></label></div>`}${step===1&&html`<div class="p-profiles-wizard-panel"><p class="p-profiles-kicker">MODEL</p><h2>Match judgment to the job.</h2><div class="p-profiles-model-choice"><button class="selected"><b>Claude Sonnet 4.5</b><span>Complex implementation and review</span></button><button><b>Claude Haiku 4.5</b><span>Fast research and classification</span></button></div><label>Thinking level<select><option>Medium — balanced</option><option>High — deliberate</option></select></label></div>`}${step===2&&html`<div class="p-profiles-wizard-panel"><p class="p-profiles-kicker">TOOLS</p><h2>Grant only what is needed.</h2><div class="p-profiles-check-list">${['Read repository files','Search issues and pull requests','Write workspace files','Run focused tests','Open pull requests'].map((x,i)=>html`<label><input type="checkbox" checked=${i<3}/> ${x}</label>`)}</div></div>`}${step===3&&html`<div class="p-profiles-wizard-panel"><p class="p-profiles-kicker">GUARDRAILS</p><h2>Make escalation predictable.</h2><label>Budget cap<input value="$10 per run"/></label><label>Approval policy<select><option>Require approval for protected changes</option></select></label><label>Allowed organization<select><option>acme-platform</option><option>side-projects</option><option>oss-maintenance</option></select></label></div>`}${step===4&&html`<div class="p-profiles-wizard-panel"><p class="p-profiles-kicker">REVIEW</p><h2>Ready to publish.</h2><dl class="p-profiles-review"><div><dt>Template</dt><dd>${chosen||'Safe scout'}</dd></div><div><dt>Model</dt><dd>Claude Sonnet 4.5 · Medium</dd></div><div><dt>Guardrail</dt><dd>Protected changes require approval</dd></div></dl></div>`}<footer><${Action} onClick=${()=>setStep(Math.max(0,step-1))}>Back</${Action}><${Action} primary=${true} onClick=${()=>step===4?toast('Profile published and ready to assign'):setStep(step+1)}>${step===4?'Publish profile':'Continue'}</${Action}></footer></main></div></section>`}
function SplitEditor({toast}){const [selected,setSelected]=useState(profiles[0]);const [edited,setEdited]=useState(false);const [assign,setAssign]=useState(false);const preview=`name: ${selected.id}\nrole: ${selected.role}\nmodel: ${selected.model}\nthinking: ${selected.thinking.toLowerCase()}\ntools:\n${selected.tools.map(x=>'  - '+x).join('\n')}\nguardrails:\n  budget_cap: ${selected.budget}\n  approval: ${selected.approval}`;return html`<section class="p-profiles-split"><header><div><p>PROFILE STUDIO</p><h1>${selected.name}</h1><span>${edited?'Draft differs from v12':'Saved version · v12'}</span></div><div><${Action} onClick=${()=>toast('Sandbox test started')}>Test run</${Action}><${Action} primary=${true} onClick=${()=>{setEdited(false);toast('Saved as v13')}}>Save version</${Action}></div></header><div class="p-profiles-split-body"><aside class="p-profiles-version-list"><b>PROFILES</b>${profiles.map(p=>html`<button class=${selected.id===p.id?'selected':''} onClick=${()=>{setSelected(p);setEdited(false)}}>${p.name}<small>${p.role}</small></button>`)}<hr/><b>VERSION HISTORY</b>${versions.map(v=>html`<button class="p-profiles-version"><strong>${v[0]}</strong><span>${v[2]}<small>${v[1]}</small></span></button>`)}</aside><form class="p-profiles-structured" onInput=${()=>setEdited(true)}><label>Role<select><option>${selected.role}</option><option>steward</option><option>scout</option><option>worker</option><option>reviewer</option></select></label><label>Model<select><option>${selected.model}</option><option>Claude Haiku 4.5</option></select></label><label>Instructions<textarea>${selected.prompt}</textarea></label><label>Allowed projects<input value=${selected.projects.join(', ')}/></label><label>Approval policy<select><option>${selected.approval}</option><option>Never merge</option></select></label><fieldset><legend>Skills</legend>${selected.skills.map(x=>html`<span>${x}</span>`)}</fieldset></form><aside class="p-profiles-code"><header><span>effective-profile.yaml</span><button onClick=${()=>toast('Preview copied')}>Copy</button></header><pre>${preview}</pre>${edited&&html`<div class="p-profiles-diff"><b>DIFF VS v12</b><span>+ guardrails.budget_cap changed</span><span>~ instructions updated</span></div>`}</aside></div><footer><span>Assignments: atlas · beacon</span><${Action} primary=${true} onClick=${()=>setAssign(true)}>Assign to agent</${Action}></footer>${assign&&html`<${AssignDialog} close=${()=>setAssign(false)} done=${text=>{toast(text);setAssign(false)}}/>`}</section>`}
function AssignDialog({close,done}){return html`<${Dialog} onClose=${close}><div class="p-profiles-assign"><p>ASSIGN PROFILE</p><h2>Apply Release steward</h2><label>Agent<select><option>atlas · acme-platform</option><option>beacon · acme-platform</option><option>forge · oss-maintenance</option><option>moss · side-projects</option></select></label><span>The agent keeps stricter local limits.</span><footer><${Action} onClick=${close}>Cancel</${Action}><${Action} primary=${true} onClick=${()=>done('Profile assigned to atlas')}>Assign</${Action}></footer></div></${Dialog}>`}
export default function ProfilesPage(){const [toast,setToast]=useState('');const notify=text=>{setToast(text);setTimeout(()=>setToast(''),2600)};return html`<main class="e-page p-profiles-page"><${PageVariants} variants=${[{key:'1',name:'Library editor',render:()=>html`<${Library} toast=${notify}/>`},{key:'2',name:'Guided setup',render:()=>html`<${Wizard} toast=${notify}/>`},{key:'3',name:'Profile studio',render:()=>html`<${SplitEditor} toast=${notify}/>`}]}/><${Toast} text=${toast}/></main>`}
